                </div>
                <button onClick={() => toggleRule(rule.id)} className={`transition-colors ${rule.active ? 'text-emerald-400' : 'text-[#a7b0c9]'}`} title={rule.active ? "ปิดใช้งาน" : "เปิดใช้งาน"}>
