const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export async function chatWithAI(message: string, history: ChatHistoryItem[] = []): Promise<string> {
  if (!apiKey) return "API Key not configured.";

  try {
    // Build context string from app data
    const teacherContext = TEACHERS.map(t => `- ${t.name} (${t.subject}, Workload: ${t.workload}%)`).join('\n');
    const activeRules = INITIAL_RULES.filter(r => r.active).map(r => `- ${r.name} (Type: ${r.type})`).join('\n');
    const scheduleSample = MOCK_SCHEDULES.slice(0, 10).map(s => {
       const t = TEACHERS.find(te => te.id === s.teacher_id);
       return `[${s.day_of_week} Period ${s.period_no}] ${s.class_name} ${s.subject} - ${t?.name}`;
    }).join('\n');

    const systemInstruction = `You are "SmartSub AI", an advanced assistant for a school substitute teacher management system.

    You have access to the following live system data:

    [TEACHERS & WORKLOAD]
    ${teacherContext}

    [ACTIVE SUBSTITUTION RULES]
    ${activeRules}

    [SCHEDULE SNAPSHOT]
    ${scheduleSample}
    ... and more.

    Your capabilities:
    1. Answer questions about teacher workloads and subjects.
    2. Explain active substitution rules and policies.
    3. Help user understand the schedule or substitute logic.
    4. Provide professional, helpful responses in Thai or English (match user's language).

    Rules:
    - Be concise.
    - If you don't have specific data (like a specific future date schedule), explain that you only have a snapshot.
    `;

    const model = 'gemini-2.5-flash';
    const contents = [
        ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        { role: 'user', parts: [{ text: message }] }
    ];

    const response = await ai.models.generateContent({
      model: model,
      contents: contents,
      config: {
        systemInstruction: systemInstruction,
      }
    });
    return response.text || "ขออภัย ไม่สามารถตอบคำถามได้ในขณะนี้";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "เกิดข้อผิดพลาดในการเชื่อมต่อกับ Gemini";
  }
}

export async function suggestSubstitute(
  absentTeacher: Teacher, 
  availableTeachers: Teacher[], 
  schedule: ScheduleItem
): Promise<string> {
  if (!apiKey) return "API Key not configured. Using fallback logic.";

  try {
    const context = `
      Absent Teacher: ${absentTeacher.name} (${absentTeacher.subject}, ${absentTeacher.grade_level}, Workload: ${absentTeacher.workload}%)
      Class needing sub: ${schedule.class_name} - ${schedule.subject}

      Available Teachers Candidates:
      ${availableTeachers.map(t => `- ${t.name} (${t.subject}, ${t.grade_level}, Workload: ${t.workload}%)`).join('\n')}

      Task: Recommend the best substitute teacher from the list. Consider subject match first, then grade level match, then workload balance.
      Provide the recommendation in JSON format: { "teacher_name": string, "reason": string }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: context,
      config: {
        responseMimeType: 'application/json',
        thinkingConfig: { thinkingBudget: 1024 } // Enable thinking for better reasoning
      }
    });

    return response.text || "{}";
  } catch (error) {
    console.error("Gemini Suggestion Error:", error);
    return "{}";
  }
}

export async function editImage(base64Image: string, prompt: string): Promise<string | null> {
  if (!apiKey) return null;

  try {
    const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, "");

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png',
              data: base64Data
            }
          },
          { text: prompt }
        ]
      }
    });

    if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
                return `data:image/png;base64,${part.inlineData.data}`;
            }
        }
    }

    return null;
  } catch (error) {
    console.error("Gemini Image Edit Error:", error);
    throw error;
  }
}

export async function analyzeRuleEffectiveness(
  rules: Rule[],
  history: SubstituteHistoryItem[],
  approvals: Approval[]
): Promise<RuleAnalysisResult | null> {
  if (!apiKey) return null;

  try {
    const context = `
      Current Rules: ${JSON.stringify(rules)}
      Substitution History: ${JSON.stringify(history)}
      Approvals/Rejections: ${JSON.stringify(approvals)}

      Task: Analyze the effectiveness of the current substitution rules based on the history.
      - Calculate an overall effectiveness score (0-100).
      - Provide a textual analysis of why rules are working or failing.
      - Suggest specific improvements.

      Output JSON format:
      {
        "analysis": "string description",
        "overallScore": number,
        "suggestions": [
          {
            "ruleId": "id of rule to modify or 'new'",
            "title": "Short title of suggestion",
            "description": "Why this change is needed",
            "action": "modify" | "create" | "remove",
            "suggestedChanges": { "weight": number, "priority": "string", "name": "string (if new)" }
          }
        ]
      }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: context,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text) as RuleAnalysisResult;
  } catch (error) {
    console.error("Gemini Rule Analysis Error:", error);
    return null;
  }
}

