export const Rules: React.FC = () => {
  const [rules, setRules] = useState(INITIAL_RULES);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<RuleAnalysisResult | null>(null);

  const toggleRule = (id: string) => {
    setRules(rules.map(r => r.id === id ? { ...r, active: !r.active } : r));
  };

  const updateRule = (id: string, updates: Partial<Rule>) => {
    setRules(rules.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const toggleReason = (ruleId: string, reason: string) => {
      const rule = rules.find(r => r.id === ruleId);
      if (!rule) return;

      const currentReasons = rule.allowedReasons || [];
      const newReasons = currentReasons.includes(reason) 
          ? currentReasons.filter(r => r !== reason)
          : [...currentReasons, reason];

      updateRule(ruleId, { allowedReasons: newReasons });
  };

  const handleDeleteRule = (id: string) => {
    if(confirm('คุณต้องการลบกฎนี้ใช่หรือไม่?')) {
        setRules(rules.filter(r => r.id !== id));
    }
  };

  const handleAddRule = () => {
    const newRule: Rule = {
      id: `rule-${Date.now()}`,
      name: 'เงื่อนไขใหม่',
      type: 'custom',
      value: '',
      priority: '2', 
      weight: 5,
      active: true,
      targetGrade: '',
      fallbackGrade: '',
      maxWorkload: 0,
      tolerance: 0,
      maxSwapsPerWeek: 0,
      allowCrossDay: false,
      noticePeriodDays: 1,
      maxSwapWindowDays: 7,
      allowedReasons: ['sick', 'personal']
    };
    setRules([...rules, newRule]);
  };

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeRuleEffectiveness(rules, MOCK_SUBSTITUTE_HISTORY, MOCK_APPROVALS);
    setAnalysisResult(result);
    setIsAnalyzing(false);
  };

  const applySuggestion = (suggestion: RuleSuggestion) => {
      if (suggestion.action === 'modify' && suggestion.suggestedChanges) {
          setRules(rules.map(r => r.id === suggestion.ruleId ? { ...r, ...suggestion.suggestedChanges } : r));
      }
      if (analysisResult) {
          setAnalysisResult({
              ...analysisResult,
              suggestions: analysisResult.suggestions.filter(s => s !== suggestion)
          });
      }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-white">เงื่อนไขอัตโนมัติ</h2>
        <Button onClick={handleAddRule}>
           <Plus size={18} className="mr-2" /> เพิ่มกฎใหม่
        </Button>
      </div>

      <div className="grid gap-4">
        {rules.map((rule) => (
          <div key={rule.id} className="bg-[#171a2e] border border-[#242c47] p-4 rounded-xl flex flex-col md:flex-row items-start md:items-center justify-between gap-4 animate-fadeIn">
             <div className="flex-1 w-full space-y-3">
                {/* Header Row: Name & Priority & Type */}
                <div className="flex flex-col md:flex-row gap-4">
                   <div className="flex-1">
                       <label className="text-[10px] text-[#a7b0c9] uppercase mb-1 block">ชื่อเงื่อนไข</label>
                       <input
                          type="text"
                          value={rule.name}
                          onChange={(e) => updateRule(rule.id, { name: e.target.value })}
                          className="w-full bg-[#0b0e1a] border border-[#242c47] rounded px-3 py-2 text-sm text-[#e9edff] focus:border-[#7aa2ff] outline-none"
                       />
                   </div>
                   <div className="w-full md:w-32">
                       <label className="text-[10px] text-[#a7b0c9] uppercase mb-1 block">ประเภท</label>
                       <select
                          value={rule.type}
                          onChange={(e) => updateRule(rule.id, { type: e.target.value as any })}
                          className="w-full bg-[#0b0e1a] border border-[#242c47] rounded px-3 py-2 text-sm text-[#e9edff] focus:border-[#7aa2ff] outline-none"
                       >
                           <option value="grade_level">ระดับชั้น</option>
                           <option value="workload_balance">ภาระงาน</option>
                           <option value="subject_match">ตรงวิชา</option>
                           <option value="period_swap">สลับคาบ</option>
                           <option value="custom">กำหนดเอง</option>
                       </select>
                   </div>
                   <div className="w-full md:w-24">
                       <label className="text-[10px] text-[#a7b0c9] uppercase mb-1 block">ความสำคัญ</label>
                       <select
