            <Card title="ข้อมูลเชิงลึก (Deep Insight)">
               <div className="space-y-5">
                  <div className="p-4 rounded-xl bg-gradient-to-br from-[#0b0e1a] to-[#1e293b] border border-[#242c47]">
                     <div className="flex items-center justify-between mb-2">
                        <div className="text-sm text-[#a7b0c9]">ภาระงานเฉลี่ย (Average)</div>
                        <TrendingUp size={16} className="text-emerald-400" />
                     </div>
                     <div className="text-3xl font-bold text-[#e9edff]">{avgLoad}%</div>
                     <div className="text-xs text-[#a7b0c9] mt-1">จากครูทั้งหมด {filteredData.length} ท่าน</div>
                  </div>

                  <div className="p-4 rounded-xl bg-gradient-to-br from-[#0b0e1a] to-[#1e293b] border border-[#242c47]">
                     <div className="flex items-center justify-between mb-2">
                        <div className="text-sm text-[#a7b0c9]">ภาระงานเกินเกณฑ์ (Overload)</div>
                        <AlertOctagon size={16} className="text-red-400" />
                     </div>
                     <div className="text-3xl font-bold text-red-400">{overLoadCount} <span className="text-base font-normal text-[#a7b0c9]">ท่าน</span></div>
                     <div className="text-xs text-[#a7b0c9] mt-1">เกินกว่า {limitLine}% ตามเงื่อนไขปัจจุบัน</div>
                  </div>

                  {topContributor && (
