                     {TEACHERS.map(t => (
                       <option key={t.id} value={t.id}>{t.name}</option>
                     ))}
                   </select>
                </div>
                <div>
                   <label className="block text-sm font-medium text-[#94a3b8] mb-1">คาบที่ต้องการจัดแทน</label>
