  title?: React.ReactNode;
  icon?: React.ReactNode;
  action?: React.ReactNode;
  active?: boolean;
  onClick?: () => void;
}

export const Card: React.FC<CardProps> = ({ 
  children, 
  className = '', 
  title, 
  icon, 
  action,
  active = false,
  onClick 
}) => {
  return (
    <div 
      onClick={onClick}
