                     className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-200 dark:border-[#334155] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-[#6366f1] text-slate-900 dark:text-[#f8fafc]"
                     value={selectedDate}
                     onChange={e => setSelectedDate(e.target.value)}
                   />
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-500 dark:text-[#94a3b8] mb-1">ครูที่ลา</label>
                   <select 
                     className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-200 dark:border-[#334155] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-[#6366f1] text-slate-900 dark:text-[#f8fafc]"
                     value={selectedTeacherId}
                     onChange={e => setSelectedTeacherId(e.target.value)}
                   >
                     <option value="">เลือกครู...</option>
                     {TEACHERS.map(t => (
                       <option key={t.id} value={t.id}>{t.name}</option>
                     ))}
                   </select>
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-500 dark:text-[#94a3b8] mb-1">คาบที่ต้องการจัดแทน</label>
                   <select 
                     className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-200 dark:border-[#334155] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-[#6366f1] text-slate-900 dark:text-[#f8fafc]"
                     value={selectedSlotId}
                     onChange={e => setSelectedSlotId(e.target.value)}
