                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-[#94a3b8] uppercase tracking-wider">สถานะ</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-slate-200 dark:divide-[#334155]">
                  {filteredHistory.length > 0 ? (
                    filteredHistory.map((item, index) => {
                       const teacher = TEACHERS.find(t => t.id === item.teacher_id);
                       const substitute = TEACHERS.find(t => t.id === item.substitute_id);
                       return (
