                                          suggestion.action === 'create' ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-500 border-emerald-200 dark:border-emerald-500/20' : 
                                          'bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-500 border-red-200 dark:border-red-500/20'
                                      }`}>
                                          {suggestion.action}
                                      </span>
                                  </div>
                                  <p className="text-xs text-slate-500 dark:text-[#94a3b8] mb-4 h-10 overflow-hidden text-ellipsis">
                                      {suggestion.description}
