                                      ปรับใช้ <ArrowRight size={14} className="ml-1" />
                                  </Button>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          )}
      </Card>

      <Card title="ตั้งค่าขั้นสูง" className="mt-8">
         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
               <label className="block text-sm font-medium text-slate-500 dark:text-[#94a3b8] mb-2">โหมดการอนุมัติ</label>
               <select className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-200 dark:border-[#334155] rounded-lg px-3 py-2 text-sm text-slate-700 dark:text-[#f8fafc]">
