export const ImageEditor: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setResultImage(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEdit = async () => {
    if (!image || !prompt) return;
    setIsProcessing(true);
    setResultImage(null);
    try {
      const result = await editImage(image, prompt);
      if (result) {
        setResultImage(result);
      }
    } catch (error) {
      alert("Failed to edit image. Check API key or quotas.");
    }
    setIsProcessing(false);
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800 dark:text-white">แต่งรูปด้วย AI (Nano Banana)</h2>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
         {/* Input Section */}
         <Card title="อัพโหลดรูปภาพ" icon={<Upload />}>
            <div className="space-y-4">
               <div 
                 onClick={() => fileInputRef.current?.click()}
                 className="border-2 border-dashed border-slate-300 dark:border-[#334155] hover:border-indigo-500 dark:hover:border-[#6366f1] rounded-xl p-8 flex flex-col items-center justify-center cursor-pointer transition-colors min-h-[250px]"
               >
                  {image ? (
                    <img src={image} alt="Original" className="max-h-[200px] object-contain rounded-lg shadow-md" />
                  ) : (
                    <>
                      <ImageIcon size={48} className="text-slate-400 dark:text-[#94a3b8] mb-4" />
                      <p className="text-slate-500 dark:text-[#94a3b8] font-medium">คลิกเพื่ออัพโหลดรูปภาพ</p>
                      <p className="text-xs text-slate-400 dark:text-[#94a3b8]/60 mt-2">รองรับ PNG, JPG</p>
                    </>
                  )}
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
               </div>

               <div>
