export const Rules: React.FC = () => {
  const [rules, setRules] = useState(INITIAL_RULES);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<RuleAnalysisResult | null>(null);

  const toggleRule = (id: string) => {
    setRules(rules.map(r => r.id === id ? { ...r, active: !r.active } : r));
  };

  const updateRule = (id: string, updates: Partial<Rule>) => {
    setRules(rules.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const toggleReason = (ruleId: string, reason: string) => {
      const rule = rules.find(r => r.id === ruleId);
      if (!rule) return;

      const currentReasons = rule.allowedReasons || [];
      const newReasons = currentReasons.includes(reason) 
          ? currentReasons.filter(r => r !== reason)
          : [...currentReasons, reason];

      updateRule(ruleId, { allowedReasons: newReasons });
  };

  const handleDeleteRule = (id: string) => {
    if(confirm('คุณต้องการลบกฎนี้ใช่หรือไม่?')) {
        setRules(rules.filter(r => r.id !== id));
    }
  };

  const handleAddRule = () => {
    const newRule: Rule = {
      id: `rule-${Date.now()}`,
      name: 'เงื่อนไขใหม่',
      type: 'custom',
      value: '',
      priority: '2', 
      weight: 5,
      active: true,
      targetGrade: '',
      fallbackGrade: '',
      maxWorkload: 0,
      tolerance: 0,
      maxSwapsPerWeek: 0,
      allowCrossDay: false,
      noticePeriodDays: 1,
      maxSwapWindowDays: 7,
      allowedReasons: ['sick', 'personal']
    };
    setRules([...rules, newRule]);
  };

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeRuleEffectiveness(rules, MOCK_SUBSTITUTE_HISTORY, MOCK_APPROVALS);
    setAnalysisResult(result);
    setIsAnalyzing(false);
  };

  const applySuggestion = (suggestion: RuleSuggestion) => {
      if (suggestion.action === 'modify' && suggestion.suggestedChanges) {
          setRules(rules.map(r => r.id === suggestion.ruleId ? { ...r, ...suggestion.suggestedChanges } : r));
      }
      if (analysisResult) {
          setAnalysisResult({
              ...analysisResult,
              suggestions: analysisResult.suggestions.filter(s => s !== suggestion)
          });
      }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">เงื่อนไขอัตโนมัติ</h2>
        <Button onClick={handleAddRule}>
           <Plus size={18} className="mr-2" /> เพิ่มกฎใหม่
        </Button>
      </div>

      <div className="grid gap-4">
        {rules.map((rule) => (
          <div key={rule.id} className="bg-white dark:bg-[#1e293b] border border-slate-200 dark:border-[#334155] p-4 rounded-xl flex flex-col md:flex-row items-start md:items-center justify-between gap-4 animate-fadeIn shadow-sm">
             <div className="flex-1 w-full space-y-3">
                {/* Header Row: Name & Priority & Type */}
                <div className="flex flex-col md:flex-row gap-4">
                   <div className="flex-1">
                       <label className="text-[10px] text-slate-500 dark:text-[#94a3b8] uppercase mb-1 block">ชื่อเงื่อนไข</label>
                       <input
                          type="text"
                          value={rule.name}
                          onChange={(e) => updateRule(rule.id, { name: e.target.value })}
                          className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-300 dark:border-[#334155] rounded px-3 py-2 text-sm text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                       />
                   </div>
                   <div className="w-full md:w-32">
                       <label className="text-[10px] text-slate-500 dark:text-[#94a3b8] uppercase mb-1 block">ประเภท</label>
                       <select
                          value={rule.type}
                          onChange={(e) => updateRule(rule.id, { type: e.target.value as any })}
                          className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-300 dark:border-[#334155] rounded px-3 py-2 text-sm text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                       >
                           <option value="grade_level">ระดับชั้น</option>
                           <option value="workload_balance">ภาระงาน</option>
                           <option value="subject_match">ตรงวิชา</option>
                           <option value="period_swap">สลับคาบ</option>
                           <option value="custom">กำหนดเอง</option>
                       </select>
                   </div>
                   <div className="w-full md:w-24">
                       <label className="text-[10px] text-slate-500 dark:text-[#94a3b8] uppercase mb-1 block">ความสำคัญ</label>
                       <select
                          value={rule.priority}
                          onChange={(e) => updateRule(rule.id, { priority: e.target.value })}
                          className="w-full bg-slate-50 dark:bg-[#0f172a] border border-slate-300 dark:border-[#334155] rounded px-3 py-2 text-sm text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                       >
                           <option value="1">High (1)</option>
                           <option value="2">Med (2)</option>
                           <option value="3">Low (3)</option>
                       </select>
                   </div>
                </div>

                {/* Conditional Inputs */}
                {rule.type === 'grade_level' && (
                   <div className="grid grid-cols-2 gap-4 p-3 bg-slate-50 dark:bg-[#0f172a]/30 rounded-lg border border-slate-200 dark:border-[#334155]/50">
                      <div>
                         <label className="block text-[10px] text-slate-500 dark:text-[#94a3b8] mb-1">Target Grade</label>
                         <input 
                            type="text"
                            value={rule.targetGrade || ''}
                            onChange={(e) => updateRule(rule.id, { targetGrade: e.target.value })}
                            className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                            placeholder="e.g. same"
                         />
                      </div>
                      <div>
                         <label className="block text-[10px] text-slate-500 dark:text-[#94a3b8] mb-1">Fallback Grade</label>
                         <input 
                            type="text"
                            value={rule.fallbackGrade || ''}
                            onChange={(e) => updateRule(rule.id, { fallbackGrade: e.target.value })}
                            className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                            placeholder="e.g. +/- 1"
                         />
                      </div>
                   </div>
                )}

                {rule.type === 'workload_balance' && (
                   <div className="grid grid-cols-2 gap-4 p-3 bg-slate-50 dark:bg-[#0f172a]/30 rounded-lg border border-slate-200 dark:border-[#334155]/50">
                      <div>
                         <label className="block text-[10px] text-slate-500 dark:text-[#94a3b8] mb-1">Max Workload (%)</label>
                         <input 
                            type="number"
                            value={rule.maxWorkload || 0}
                            onChange={(e) => updateRule(rule.id, { maxWorkload: parseInt(e.target.value) || 0 })}
                            className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                         />
                      </div>
                      <div>
                         <label className="block text-[10px] text-slate-500 dark:text-[#94a3b8] mb-1">Tolerance</label>
                         <input 
                            type="number"
                            value={rule.tolerance || 0}
                            onChange={(e) => updateRule(rule.id, { tolerance: parseInt(e.target.value) || 0 })}
                            className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                         />
                      </div>
                   </div>
                )}

                {rule.type === 'period_swap' && (
                   <div className="col-span-2 p-4 bg-indigo-50 dark:bg-indigo-500/10 border border-indigo-100 dark:border-indigo-500/20 rounded-lg space-y-4">
                      <h4 className="text-xs font-bold text-indigo-500 dark:text-indigo-300 flex items-center gap-2">
                         <Shuffle size={12} /> รายละเอียดการแลกเปลี่ยน (Swap Detail)
                      </h4>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div>
                             <label className="block text-[10px] text-slate-500 dark:text-[#94a3b8] mb-1">Max Swaps / Week (สูงสุดต่อสัปดาห์)</label>
                             <input 
                                type="number"
                                value={rule.maxSwapsPerWeek || 0}
                                onChange={(e) => updateRule(rule.id, { maxSwapsPerWeek: parseInt(e.target.value) || 0 })}
                                className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                             />
                          </div>
                          <div>
                             <label className="block text-[10px] text-slate-500 dark:text-[#94a3b8] mb-1 flex items-center gap-1">
                                <Clock size={10}/> ระยะเวลาขออนุมัติล่วงหน้า (วัน)
                             </label>
                             <input 
                                type="number"
                                value={rule.noticePeriodDays || 0}
                                onChange={(e) => updateRule(rule.id, { noticePeriodDays: parseInt(e.target.value) || 0 })}
                                className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                                placeholder="e.g. 3 days before"
                             />
                          </div>
