                             <input 
                                type="number"
                                value={rule.maxSwapWindowDays || 0}
                                onChange={(e) => updateRule(rule.id, { maxSwapWindowDays: parseInt(e.target.value) || 0 })}
                                className="w-full bg-white dark:bg-[#1e293b] border border-slate-300 dark:border-[#334155] rounded px-2 py-1 text-xs text-slate-700 dark:text-[#f8fafc] focus:border-indigo-500 dark:focus:border-[#6366f1] outline-none"
                                placeholder="e.g. within 14 days"
                             />
