                          <div className="flex flex-wrap gap-3">
                              {[
                                  { key: 'sick', label: 'ลาป่วย', icon: <AlertCircle size={10}/> },
                                  { key: 'personal', label: 'ลากิจ', icon: <User size={10}/> },
