                                  <div key={reason.key} className="flex items-center gap-1.5 bg-white dark:bg-[#0f172a] px-2 py-1 rounded border border-slate-200 dark:border-[#334155]">
                                      <input 
                                          type="checkbox"
                                          checked={(rule.allowedReasons || []).includes(reason.key)}
                                          onChange={() => toggleReason(rule.id, reason.key)}
                                          className="w-3 h-3 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
