                <button 
                    onClick={() => handleDeleteRule(rule.id)}
                    className="text-red-500 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-400/10 p-2 rounded-lg transition-colors"
                    title="ลบกฎ"
                >
                   <Trash2 size={18} />
