                  <div className="p-4 rounded-xl bg-gradient-to-br from-slate-50 to-slate-100 dark:from-[#0f172a] dark:to-[#1e293b] border border-slate-200 dark:border-[#334155]">
                     <div className="flex items-center justify-between mb-2">
                        <div className="text-sm text-slate-500 dark:text-[#94a3b8]">ภาระงานเฉลี่ย (Average)</div>
