export const Workload: React.FC = () => {
  const [sortBy, setSortBy] = useState<'workload_desc' | 'workload_asc' | 'name'>('workload_desc');
  const [filterSubject, setFilterSubject] = useState<string>('All');

  // Calculate workload dynamically including substitute history
  const data = TEACHERS.map(t => {
    // Count substituted classes from history where status is completed
    const subCount = MOCK_SUBSTITUTE_HISTORY.filter(
        h => h.substitute_id === t.id && h.status === 'completed'
    ).length;

    // Assume each substitution adds ~5% (mock logic) or use real calculation
    const subLoad = subCount * 5; 

    return {
      name: t.name,
      shortName: t.name.split(' ')[0],
      regularLoad: t.workload,
      subLoad: subLoad,
      totalLoad: t.workload + subLoad,
      subject: t.subject,
      grade: t.grade_level,
      full: t
    };
  });

  // Filter & Sort
  const filteredData = data.filter(d => 
      filterSubject === 'All' || d.subject === filterSubject
  ).sort((a, b) => {
      if (sortBy === 'workload_desc') return b.totalLoad - a.totalLoad;
      if (sortBy === 'workload_asc') return a.totalLoad - b.totalLoad;
      return a.name.localeCompare(b.name);
  });

  // Dynamic Height calculation: 60px per bar + header buffer
  const chartHeight = Math.max(500, filteredData.length * 60);

  // Get active workload limit rule
  const workloadRule = INITIAL_RULES.find(r => r.type === 'workload_balance' && r.active);
  const limitLine = workloadRule?.maxWorkload || 80;

  // Stats for sidebar
  const avgLoad = Math.round(filteredData.reduce((acc, curr) => acc + curr.totalLoad, 0) / (filteredData.length || 1));
  const overLoadCount = filteredData.filter(d => d.totalLoad > limitLine).length;
  const topContributor = filteredData.sort((a,b) => b.subLoad - a.subLoad)[0];

  const uniqueSubjects = Array.from(new Set(TEACHERS.map(t => t.subject)));

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
         <h2 className="text-2xl font-bold text-slate-800 dark:text-white">ภาระงานและสถิติ (Workload Analytics)</h2>
         <div className="flex flex-wrap gap-2">
             <select 
                value={filterSubject}
                onChange={(e) => setFilterSubject(e.target.value)}
                className="bg-slate-50 dark:bg-slate-950 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-700 dark:text-slate-200 focus:border-indigo-500 dark:focus:border-indigo-500 outline-none"
             >
                <option value="All">ทุกวิชา (All Subjects)</option>
                {uniqueSubjects.map(s => <option key={s} value={s}>{s}</option>)}
             </select>
             <select 
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-950 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-700 dark:text-slate-200 focus:border-indigo-500 dark:focus:border-indigo-500 outline-none"
             >
                <option value="workload_desc">ภาระงานมาก-น้อย</option>
                <option value="workload_asc">ภาระงานน้อย-มาก</option>
                <option value="name">ชื่อ ก-ฮ</option>
             </select>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
         <div className="lg:col-span-2">
            <Card title={`กราฟเปรียบเทียบเชิงลึก (${filteredData.length} ท่าน)`} className="h-full min-h-[600px] flex flex-col">
               <div className="flex-1 w-full overflow-y-auto pr-2 custom-scrollbar" style={{ maxHeight: '600px' }}>
                 <div style={{ height: `${chartHeight}px`, width: '100%' }}>
                   <ResponsiveContainer width="100%" height="100%">
                     <BarChart 
                        data={filteredData} 
                        layout="vertical" 
                        margin={{ top: 20, right: 30, left: 40, bottom: 5 }}
                        barSize={20}
                        stackOffset="sign"
                     >
                       <CartesianGrid strokeDasharray="3 3" stroke="#cbd5e1" horizontal={false} className="dark:stroke-slate-800" />
                       <XAxis type="number" stroke="#94a3b8" domain={[0, 100]} />
                       <YAxis dataKey="shortName" type="category" stroke="#94a3b8" width={100} tick={{fontSize: 12}} />
                       <Tooltip 
                          cursor={{fill: '#94a3b8', opacity: 0.1}}
                          contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#f8fafc', borderRadius: '8px' }}
                          itemStyle={{ color: '#f8fafc', fontSize: '12px' }}
                          formatter={(value: number, name: string) => [
                              `${value}%`, 
                              name === 'regularLoad' ? 'ภาระงานปกติ' : 'ภาระงานสอนแทน'
                          ]}
                          labelStyle={{ color: '#6366f1', fontWeight: 'bold', marginBottom: '5px' }}
                       />
                       <Legend verticalAlign="top" height={36} wrapperStyle={{fontSize: '12px'}} />
                       <ReferenceLine x={limitLine} stroke="#ef4444" strokeDasharray="3 3" label={{ position: 'top', value: `Limit (${limitLine}%)`, fill: '#ef4444', fontSize: 10 }} />

                       <Bar dataKey="regularLoad" name="ภาระงานปกติ" stackId="a" fill="#3b82f6" radius={[0, 0, 0, 0]} />
                       <Bar dataKey="subLoad" name="ภาระงานสอนแทน" stackId="a" fill="#8b5cf6" radius={[0, 4, 4, 0]}>
                          {filteredData.map((entry, index) => (
                             <Cell key={`cell-${index}`} fill={entry.totalLoad > limitLine ? '#ef4444' : '#8b5cf6'} />
                          ))}
                       </Bar>
                     </BarChart>
                   </ResponsiveContainer>
                 </div>
               </div>
               <div className="mt-4 text-xs text-slate-500 dark:text-slate-400 flex items-center justify-center gap-4 border-t border-slate-200 dark:border-slate-800 pt-4">
                  <div className="flex items-center gap-2"><div className="w-3 h-3 bg-blue-500 rounded-sm"></div> งานสอนปกติ</div>
                  <div className="flex items-center gap-2"><div className="w-3 h-3 bg-purple-500 rounded-sm"></div> สอนแทน (Substitute)</div>
                  <div className="flex items-center gap-2"><div className="w-3 h-3 bg-red-500 rounded-sm"></div> เกินเกณฑ์ (Overload)</div>
               </div>
            </Card>
         </div>

         <div className="space-y-6">
            <Card title="ข้อมูลเชิงลึก (Deep Insight)">
               <div className="space-y-5">
                  <div className="p-4 rounded-xl bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 border border-slate-200 dark:border-slate-800">
                     <div className="flex items-center justify-between mb-2">
                        <div className="text-sm text-slate-500 dark:text-slate-400">ภาระงานเฉลี่ย (Average)</div>
                        <TrendingUp size={16} className="text-emerald-500 dark:text-emerald-400" />
                     </div>
                     <div className="text-3xl font-bold text-slate-800 dark:text-slate-200">{avgLoad}%</div>
                     <div className="text-xs text-slate-500 dark:text-slate-400 mt-1">จากครูทั้งหมด {filteredData.length} ท่าน</div>
                  </div>

                  <div className="p-4 rounded-xl bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 border border-slate-200 dark:border-slate-800">
                     <div className="flex items-center justify-between mb-2">
                        <div className="text-sm text-slate-500 dark:text-slate-400">ภาระงานเกินเกณฑ์ (Overload)</div>
                        <AlertOctagon size={16} className="text-red-500 dark:text-red-400" />
                     </div>
                     <div className="text-3xl font-bold text-red-500 dark:text-red-400">{overLoadCount} <span className="text-base font-normal text-slate-500 dark:text-slate-400">ท่าน</span></div>
                     <div className="text-xs text-slate-500 dark:text-slate-400 mt-1">เกินกว่า {limitLine}% ตามเงื่อนไขปัจจุบัน</div>
                  </div>

                  {topContributor && (
                      <div className="p-4 rounded-xl bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 border border-slate-200 dark:border-slate-800">
                         <div className="flex items-center justify-between mb-2">
                            <div className="text-sm text-slate-500 dark:text-slate-400">ช่วยสอนแทนสูงสุด (Top Contributor)</div>
                            <UserPlus size={16} className="text-indigo-600 dark:text-indigo-400" />
                         </div>
                         <div className="flex items-center gap-3 mt-2">
                            {topContributor.full.avatar && <img src={topContributor.full.avatar} className="w-10 h-10 rounded-full border border-indigo-500 dark:border-indigo-400" />}
                            <div>
                                <div className="font-bold text-slate-800 dark:text-white">{topContributor.name}</div>
                                <div className="text-xs text-indigo-600 dark:text-indigo-400">Substitute Load: +{topContributor.subLoad}%</div>
                            </div>
                         </div>
                      </div>
                  )}
               </div>
            </Card>

            <Card title="เกณฑ์ (Conditions)">
                <div className="space-y-3">
                    <div className="flex justify-between items-center p-2 rounded bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800">
                        <span className="text-xs text-slate-500 dark:text-slate-400">Max Workload</span>
                        <span className="text-xs font-bold text-red-500 dark:text-red-400">{limitLine}%</span>
                    </div>
                    <div className="flex justify-between items-center p-2 rounded bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800">
                        <span className="text-xs text-slate-500 dark:text-slate-400">Substitute Weight</span>
                        <span className="text-xs font-bold text-purple-500 dark:text-purple-400">~5% /คาบ</span>
                    </div>
                    <p className="text-[10px] text-slate-400 dark:text-slate-500 mt-2">
                        *เกณฑ์เหล่านี้อ้างอิงจากหน้า "เงื่อนไขอัตโนมัติ" และมีผลต่อการคำนวณกราฟด้านซ้าย
                    </p>
                </div>
            </Card>
         </div>
      </div>
    </div>
  );
};

