                                  <circle cx="64" cy="64" r="56" stroke="#cbd5e1" strokeWidth="12" fill="transparent" className="dark:stroke-slate-800" />
                                  <circle cx="64" cy="64" r="56" stroke={analysisResult.overallScore > 70 ? '#4ade80' : analysisResult.overallScore > 40 ? '#fbbf24' : '#f87171'} strokeWidth="12" fill="transparent" strokeDasharray={`${analysisResult.overallScore * 3.51} 351`} className="transition-all duration-1000 ease-out" />
                              </svg>
                              <span className="absolute text-3xl font-bold text-slate-800 dark:text-white">{analysisResult.overallScore}</span>
                          </div>
                      </div>
                      <div className="md:col-span-2 p-6 bg-white dark:bg-slate-950/50 rounded-xl border border-slate-200 dark:border-slate-800">
                          <h4 className="font-semibold text-slate-800 dark:text-slate-200 mb-2 flex items-center gap-2">
                              <BarChart2 size={18} className="text-indigo-500 dark:text-indigo-400" /> ผลการวิเคราะห์
                          </h4>
                          <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">
                              {analysisResult.analysis}
                          </p>
                      </div>
                  </div>

                  <div>
                      <h4 className="font-semibold text-slate-800 dark:text-slate-200 mb-4">ข้อเสนอแนะในการปรับปรุง</h4>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {analysisResult.suggestions.map((suggestion, idx) => (
                              <div key={idx} className="p-4 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 hover:border-indigo-500 dark:hover:border-indigo-500 rounded-xl transition-all shadow-sm">
