                                      <h5 className="font-semibold text-slate-800 dark:text-white">{suggestion.title}</h5>
                                      <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase border ${
                                          suggestion.action === 'modify' ? 'bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-500 border-amber-200 dark:border-amber-500/20' : 
                                          suggestion.action === 'create' ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-500 border-emerald-200 dark:border-emerald-500/20' : 
                                          'bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-500 border-red-200 dark:border-red-500/20'
                                      }`}>
                                          {suggestion.action}
                                      </span>
                                  </div>
                                  <p className="text-xs text-slate-500 dark:text-slate-400 mb-4 h-10 overflow-hidden text-ellipsis">
                                      {suggestion.description}
                                  </p>
                                  {suggestion.suggestedChanges && suggestion.suggestedChanges.weight && (
                                       <div className="text-xs text-indigo-600 dark:text-indigo-400 mb-3 bg-indigo-50 dark:bg-indigo-500/10 p-2 rounded inline-block">
