                                       </div>
                                  )}
                                  <Button 
                                      size="sm" 
                                      variant="secondary" 
                                      className="w-full" 
                                      onClick={() => applySuggestion(suggestion)}
                                  >
                                      ปรับใช้ <ArrowRight size={14} className="ml-1" />
                                  </Button>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          )}
      </Card>

      <Card title="ตั้งค่าขั้นสูง" className="mt-8">
         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
               <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-2">โหมดการอนุมัติ</label>
               <select className="w-full bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-700 dark:text-slate-200">
                  <option>อนุมัติอัตโนมัติ (แนะนำ)</option>
                  <option>ส่งให้หัวหน้าวิชาการอนุมัติ</option>
                  <option>อนุมัติเฉพาะกรณีข้ามสายชั้น</option>
               </select>
            </div>
            <div>
               <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-2">การแจ้งเตือน</label>
               <select className="w-full bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-700 dark:text-slate-200">
                  <option>แจ้งครูสอนแทนทันที</option>
                  <option>แจ้งสรุปรายวัน</option>
                  <option>ไม่แจ้ง</option>
               </select>
            </div>
         </div>
         <div className="mt-6 flex justify-end">
            <Button variant="success">
               <Save size={18} className="mr-2" /> บันทึกการตั้งค่า
            </Button>
         </div>
      </Card>
    </div>
  );
};

