    const searchLower = searchQuery.toLowerCase();

    return (
      (teacher?.name || '').toLowerCase().includes(searchLower) ||
      (sub?.name || '').toLowerCase().includes(searchLower) ||
      approval.subject.toLowerCase().includes(searchLower)
