        <div className="relative w-full sm:w-auto">
           <input 
             type="text" 
             placeholder="ค้นหาชื่อครู, วิชา..." 
             className="w-full sm:w-64 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-indigo-500 text-slate-900 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-600"
             value={searchQuery}
             onChange={(e) => setSearchQuery(e.target.value)}
           />
           <Search size={16} className="absolute left-3 top-3 text-slate-400 dark:text-slate-500" />
        </div>
      </div>

      <div className="space-y-4">
        {filteredApprovals.length > 0 ? (
          filteredApprovals.map((approval) => {
            const teacher = TEACHERS.find(t => t.id === approval.teacher_id);
            const sub = TEACHERS.find(t => t.id === approval.substitute_id);

            return (
              <Card key={approval.id} className="border-l-4 border-l-amber-400">
                 <div className="flex flex-col md:flex-row justify-between gap-4">
                    <div className="flex-1">
                       <div className="flex items-center gap-2 mb-2">
                          <span className="px-2 py-1 rounded-md bg-amber-100 dark:bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold border border-amber-200 dark:border-amber-500/20 flex items-center gap-1">
                             <Clock size={12} /> Pending
                          </span>
                          <span className="text-sm text-slate-500 dark:text-slate-400">Requested: {approval.requestedAt}</span>
                       </div>
                       <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-1">
                          {approval.subject} - คาบ {approval.period}
                       </h3>
                       <div className="text-sm text-slate-500 dark:text-slate-400">
                          <span className="text-slate-800 dark:text-slate-200">{teacher?.name}</span> (ลา) 
                          <span className="mx-2">→</span>
                          <span className="text-indigo-600 dark:text-indigo-400">{sub?.name}</span> (สอนแทน)
                       </div>
                       <div className="mt-2 text-xs text-slate-400 dark:text-slate-500">
                          ขอโดย: {approval.requestedBy}
                       </div>
                    </div>

                    <div className="flex items-center gap-3">
                       <Button variant="success" size="sm">
                          <Check size={16} className="mr-1" /> อนุมัติ
                       </Button>
                       <Button variant="danger" size="sm">
                          <X size={16} className="mr-1" /> ปฏิเสธ
                       </Button>
                    </div>
                 </div>
              </Card>
            );
          })
        ) : (
          <div className="flex flex-col items-center justify-center py-12 text-slate-400 dark:text-slate-600 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800">
             <Search size={48} className="mb-4 opacity-20" />
             <p>ไม่พบรายการที่ค้นหา</p>
          </div>
        )}
      </div>
    </div>
  );
};

