          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div 
                  onClick={() => handleDataSourceChange('mock')}
                  className={`p-4 rounded-xl border cursor-pointer transition-all flex flex-col items-center justify-center gap-2 ${dataSource === 'mock' ? 'bg-indigo-50 dark:bg-indigo-500/10 border-indigo-500 dark:border-indigo-500 text-indigo-700 dark:text-white' : 'bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 text-slate-500 dark:text-slate-400 hover:border-indigo-300 dark:hover:border-indigo-500/50'}`}
              >
