  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [dataSource, setDataSource] = useState<'mock' | 'sheets' | 'excel'>('mock');

  useEffect(() => {
    const storedSource = localStorage.getItem('smartsub_data_source');
    if (storedSource) setDataSource(storedSource as any);
    loadHistory(storedSource as any || 'mock');
  }, []);

  const loadHistory = async (sourceOverride?: 'mock' | 'sheets' | 'excel') => {
    setIsLoadingHistory(true);
    const source = sourceOverride || dataSource;

    let data: SubstituteHistoryItem[] | null = null;

    if (source === 'sheets') {
        data = await SheetService.getSubstituteHistory();
    } else if (source === 'excel') {
        data = ExcelService.getLocalData();
    } 

    if (data) {
        setHistoryData(data);
    } else {
        if (source !== 'mock') console.warn(`Failed to load from ${source}, falling back to mock.`);
        setHistoryData(MOCK_SUBSTITUTE_HISTORY);
    }

    setIsLoadingHistory(false);
  };

  const handleAISuggest = async () => {
    if (!selectedTeacherId || !selectedSlotId) return;

    setIsAnalyzing(true);
    const absentTeacher = TEACHERS.find(t => t.id === selectedTeacherId);
    const schedule = MOCK_SCHEDULES.find(s => s.teacher_id === selectedTeacherId); 

    if (absentTeacher && schedule) {
      const availableTeachers = TEACHERS.filter(t => t.id !== selectedTeacherId);
      const resultJson = await suggestSubstitute(absentTeacher, availableTeachers, schedule);
      try {
        const parsed = JSON.parse(resultJson);
        setSuggestion({
            name: parsed.teacher_name || parsed.teacherName,
            reason: parsed.reason
        });
      } catch (e) {
        setSuggestion({
            name: "Error parsing AI response",
            reason: resultJson
        });
      }
    }
    setIsAnalyzing(false);
  };

  const filteredHistory = historyData.filter(item => {
    const teacher = TEACHERS.find(t => t.id === item.teacher_id);
    const substitute = TEACHERS.find(t => t.id === item.substitute_id);
    const searchLower = historySearch.toLowerCase();

    return (
      item.subject.toLowerCase().includes(searchLower) ||
      (teacher?.name || '').toLowerCase().includes(searchLower) ||
      (substitute?.name || '').toLowerCase().includes(searchLower) ||
      item.date.includes(searchLower)
    );
  });

  return (
    <div className="space-y-6">
       <h2 className="text-2xl font-bold text-slate-800 dark:text-white">จัดการสอนแทน</h2>

       <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card title="ข้อมูลการลา" icon={<UserPlus />}>
             <div className="space-y-4">
                <div>
                   <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-1">วันที่</label>
                   <input 
                     type="date" 
                     className="w-full bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-indigo-500 text-slate-900 dark:text-slate-200"
                     value={selectedDate}
                     onChange={e => setSelectedDate(e.target.value)}
                   />
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-1">ครูที่ลา</label>
                   <select 
                     className="w-full bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-indigo-500 text-slate-900 dark:text-slate-200"
                     value={selectedTeacherId}
                     onChange={e => setSelectedTeacherId(e.target.value)}
                   >
                     <option value="">เลือกครู...</option>
                     {TEACHERS.map(t => (
                       <option key={t.id} value={t.id}>{t.name}</option>
                     ))}
                   </select>
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-1">คาบที่ต้องการจัดแทน</label>
                   <select 
                     className="w-full bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-indigo-500 text-slate-900 dark:text-slate-200"
                     value={selectedSlotId}
                     onChange={e => setSelectedSlotId(e.target.value)}
                   >
                      <option value="">เลือกคาบ...</option>
                      {TIME_SLOTS.map((slot) => (
                        <option key={slot.id} value={slot.id}>
                          คาบ {slot.period_no} ({slot.time_label})
                        </option>
                      ))}
                   </select>
                </div>

                <Button 
                   onClick={handleAISuggest} 
                   disabled={!selectedTeacherId || !selectedSlotId || isAnalyzing}
                   className="w-full mt-4"
                >
                   {isAnalyzing ? (
                       <>กำลังวิเคราะห์...</>
                   ) : (
                       <><Brain size={18} className="mr-2" /> ให้ AI แนะนำผู้สอนแทน</>
                   )}
                </Button>
             </div>
          </Card>

          <Card title="ผลการวิเคราะห์ AI" className={!suggestion ? 'opacity-50 pointer-events-none' : ''}>
             {suggestion ? (
                 <div className="space-y-4 animate-fadeIn">
                     <div className="p-4 bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-200 dark:border-emerald-500/30 rounded-lg">
                        <div className="text-sm text-emerald-600 dark:text-emerald-400 font-bold mb-1">แนะนำ:</div>
                        <div className="text-xl font-bold text-slate-800 dark:text-white">{suggestion.name}</div>
                     </div>
                     <div className="p-4 bg-slate-50 dark:bg-slate-950 rounded-lg border border-slate-200 dark:border-slate-800">
                        <div className="text-sm text-slate-500 dark:text-slate-400 font-bold mb-2">เหตุผลประกอบ:</div>
                        <p className="text-sm text-slate-700 dark:text-slate-300 leading-relaxed">
                            {suggestion.reason}
                        </p>
                     </div>
                     <div className="flex gap-3 mt-4">
                        <Button variant="success" className="flex-1">
                            <Check size={18} className="mr-2" /> ยืนยันการจัดแทน
                        </Button>
                        <Button variant="secondary" className="flex-1">
                            ปฏิเสธ
                        </Button>
                     </div>
                 </div>
             ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-600 py-12">
                     <Brain size={48} className="mb-4 opacity-20" />
                     <p>เลือกข้อมูลและกดปุ่มวิเคราะห์เพื่อรับคำแนะนำ</p>
                 </div>
             )}
          </Card>
       </div>

       <Card 
         title={
           <div className="flex items-center gap-2">
             <span>ประวัติการสอนแทน</span>
             {dataSource === 'sheets' && (
               <span className="flex items-center gap-1 text-[10px] bg-green-100 dark:bg-green-500/20 text-green-600 dark:text-green-400 border border-green-200 dark:border-green-500/30 px-2 py-0.5 rounded">
                  <LinkIcon size={10} /> Google Sheets
               </span>
             )}
             {dataSource === 'excel' && (
               <span className="flex items-center gap-1 text-[10px] bg-emerald-100 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-500/30 px-2 py-0.5 rounded">
                  <FileSpreadsheet size={10} /> Excel (Local)
               </span>
             )}
             {dataSource === 'mock' && (
               <span className="flex items-center gap-1 text-[10px] bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-slate-300 border border-gray-200 dark:border-slate-600 px-2 py-0.5 rounded">
                  <Database size={10} /> Mock
               </span>
             )}
           </div>
         } 
         icon={<History />}
         action={
           <div className="flex gap-2">
             <div className="relative">
               <input 
                 type="text" 
                 placeholder="ค้นหา..." 
                 className="bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg pl-9 pr-3 py-1.5 text-xs focus:outline-none focus:border-indigo-500 dark:focus:border-indigo-500 w-40 text-slate-900 dark:text-slate-200"
                 value={historySearch}
                 onChange={(e) => setHistorySearch(e.target.value)}
               />
               <Search size={14} className="absolute left-3 top-2 text-slate-400 dark:text-slate-500" />
             </div>
             <Button variant="secondary" size="sm" onClick={() => loadHistory()} isLoading={isLoadingHistory}>
               <RefreshCw size={14} />
             </Button>
           </div>
         }
       >
          <div className="overflow-x-auto">
             <table className="w-full text-left border-collapse">
               <thead>
                  <tr className="border-b border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30">
                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        <div className="flex items-center gap-2"><CalendarIcon size={14} /> วันที่</div>
                     </th>
                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">คาบ</th>
                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        <div className="flex items-center gap-2"><BookOpen size={14} /> วิชา</div>
                     </th>
                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        <div className="flex items-center gap-2"><User size={14} /> ครูเจ้าของวิชา</div>
                     </th>
                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        <div className="flex items-center gap-2"><UserPlus size={14} /> ครูสอนแทน</div>
                     </th>
                     <th className="p-4 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">สถานะ</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                  {filteredHistory.length > 0 ? (
                    filteredHistory.map((item, index) => {
                       const teacher = TEACHERS.find(t => t.id === item.teacher_id);
                       const substitute = TEACHERS.find(t => t.id === item.substitute_id);
                       return (
                          <tr key={item.id || index} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                             <td className="p-4 text-sm text-slate-700 dark:text-slate-300">{item.date}</td>
                             <td className="p-4">
                                <span className="inline-flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 text-sm font-bold text-indigo-600 dark:text-indigo-400">
                                   {item.period}
                                </span>
                             </td>
                             <td className="p-4 text-sm text-slate-700 dark:text-slate-300">{item.subject}</td>
                             <td className="p-4 text-sm text-slate-500 dark:text-slate-400">{teacher?.name || item.teacher_id}</td>
                             <td className="p-4 text-sm text-indigo-600 dark:text-indigo-400">{substitute?.name || item.substitute_id}</td>
                             <td className="p-4">
                                <span className={`px-2 py-1 rounded text-xs font-medium border ${
                                   item.status === 'completed' 
                                   ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-200 dark:border-emerald-500/20' 
                                   : 'bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-400 border-red-200 dark:border-red-500/20'
                                }`}>
                                   {item.status === 'completed' ? 'เรียบร้อย' : 'ยกเลิก'}
                                </span>
                             </td>
                          </tr>
                       );
                    })
                  ) : (
                    <tr>
                       <td colSpan={6} className="p-8 text-center text-slate-500 dark:text-slate-500">ไม่พบข้อมูลประวัติการสอนแทน</td>
                    </tr>
                  )}
               </tbody>
             </table>
          </div>
       </Card>
    </div>
  );
};

