export const Rules: React.FC = () => {
  const [rules, setRules] = useState(INITIAL_RULES);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<RuleAnalysisResult | null>(null);

  const toggleRule = (id: string) => {
    setRules(rules.map(r => r.id === id ? { ...r, active: !r.active } : r));
  };

  const updateRule = (id: string, updates: Partial<Rule>) => {
    setRules(rules.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const toggleReason = (ruleId: string, reason: string) => {
      const rule = rules.find(r => r.id === ruleId);
      if (!rule) return;

      const currentReasons = rule.allowedReasons || [];
      const newReasons = currentReasons.includes(reason) 
          ? currentReasons.filter(r => r !== reason)
          : [...currentReasons, reason];

      updateRule(ruleId, { allowedReasons: newReasons });
  };

  const handleDeleteRule = (id: string) => {
    if(confirm('คุณต้องการลบกฎนี้ใช่หรือไม่?')) {
        setRules(rules.filter(r => r.id !== id));
    }
  };

  const handleAddRule = () => {
    const newRule: Rule = {
      id: `rule-${Date.now()}`,
      name: 'เงื่อนไขใหม่',
      type: 'custom',
      value: '',
      priority: '2', 
      weight: 5,
      active: true,
      targetGrade: '',
      fallbackGrade: '',
      maxWorkload: 0,
      tolerance: 0,
      maxSwapsPerWeek: 0,
      allowCrossDay: false,
      noticePeriodDays: 1,
      maxSwapWindowDays: 7,
      allowedReasons: ['sick', 'personal']
    };
    setRules([...rules, newRule]);
  };

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await analyzeRuleEffectiveness(rules, MOCK_SUBSTITUTE_HISTORY, MOCK_APPROVALS);
    setAnalysisResult(result);
    setIsAnalyzing(false);
  };

  const applySuggestion = (suggestion: RuleSuggestion) => {
      if (suggestion.action === 'modify' && suggestion.suggestedChanges) {
          setRules(rules.map(r => r.id === suggestion.ruleId ? { ...r, ...suggestion.suggestedChanges } : r));
      }
      if (analysisResult) {
          setAnalysisResult({
              ...analysisResult,
              suggestions: analysisResult.suggestions.filter(s => s !== suggestion)
          });
      }
  };

  return (
