                  </div>
              </div>
              <Button onClick={handleAnalyze} disabled={isAnalyzing} isLoading={isAnalyzing}>
                  {isAnalyzing ? 'กำลังวิเคราะห์...' : 'เริ่มการวิเคราะห์'}
              </Button>
          </div>

          {analysisResult && (
              <div className="space-y-6 animate-fadeIn">
