                                      <h5 className="font-bold text-slate-800 dark:text-white">{suggestion.title}</h5>
                                      <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase border ${
                                          suggestion.action === 'modify' ? 'bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-500 border-amber-200 dark:border-amber-500/20' : 
                                          suggestion.action === 'create' ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-500 border-emerald-200 dark:border-emerald-500/20' : 
                                          'bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-500 border-red-200 dark:border-red-500/20'
                                      }`}>
                                          {suggestion.action}
                                      </span>
                                  </div>
                                  <p className="text-xs text-slate-600 dark:text-slate-400 mb-4 h-10 overflow-hidden text-ellipsis font-medium">
                                      {suggestion.description}
                                  </p>
                                  {suggestion.suggestedChanges && suggestion.suggestedChanges.weight && (
                                       <div className="text-xs text-indigo-700 dark:text-indigo-400 mb-3 bg-indigo-50 dark:bg-indigo-500/10 p-2 rounded inline-block font-bold">
                                           Weight: {rules.find(r => r.id === suggestion.ruleId)?.weight} → {suggestion.suggestedChanges.weight}
                                       </div>
                                  )}
                                  <Button 
                                      size="sm" 
                                      variant="secondary" 
                                      className="w-full font-bold" 
                                      onClick={() => applySuggestion(suggestion)}
                                  >
                                      ปรับใช้ <ArrowRight size={14} className="ml-1" />
                                  </Button>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          )}
      </Card>

      <Card title="ตั้งค่าขั้นสูง" className="mt-8">
         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
               <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">โหมดการอนุมัติ</label>
               <select className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-900 dark:text-slate-100 font-medium">
                  <option>อนุมัติอัตโนมัติ (แนะนำ)</option>
                  <option>ส่งให้หัวหน้าวิชาการอนุมัติ</option>
                  <option>อนุมัติเฉพาะกรณีข้ามสายชั้น</option>
               </select>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">การแจ้งเตือน</label>
               <select className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-900 dark:text-slate-100 font-medium">
