                  <option>แจ้งสรุปรายวัน</option>
                  <option>ไม่แจ้ง</option>
               </select>
            </div>
         </div>
         <div className="mt-6 flex justify-end">
            <Button variant="success" className="font-bold">
               <Save size={18} className="mr-2" /> บันทึกการตั้งค่า
            </Button>
         </div>
      </Card>
    </div>
  );
};

