export const ImageEditor: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setResultImage(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEdit = async () => {
    if (!image || !prompt) return;
    setIsProcessing(true);
    setResultImage(null);
    try {
      const result = await editImage(image, prompt);
      if (result) {
        setResultImage(result);
      }
    } catch (error) {
      alert("Failed to edit image. Check API key or quotas.");
    }
    setIsProcessing(false);
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-900 dark:text-white">แต่งรูปด้วย AI (Nano Banana)</h2>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
         {/* Input Section */}
         <Card title="อัพโหลดรูปภาพ" icon={<Upload />}>
            <div className="space-y-4">
               <div 
                 onClick={() => fileInputRef.current?.click()}
                 className="border-2 border-dashed border-slate-300 dark:border-slate-700 hover:border-indigo-500 dark:hover:border-indigo-500 rounded-xl p-8 flex flex-col items-center justify-center cursor-pointer transition-colors min-h-[250px]"
               >
                  {image ? (
                    <img src={image} alt="Original" className="max-h-[200px] object-contain rounded-lg shadow-md" />
                  ) : (
                    <>
                      <ImageIcon size={48} className="text-slate-400 dark:text-slate-500 mb-4" />
                      <p className="text-slate-600 dark:text-slate-400 font-bold">คลิกเพื่ออัพโหลดรูปภาพ</p>
                      <p className="text-xs text-slate-500 dark:text-slate-500 mt-2 font-medium">รองรับ PNG, JPG</p>
                    </>
                  )}
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
               </div>

               <div>
                 <label className="block text-sm font-bold text-slate-600 dark:text-slate-400 mb-2">คำสั่ง (Prompt)</label>
                 <textarea 
                   className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg p-3 text-sm focus:outline-none focus:border-indigo-500 dark:focus:border-indigo-500 text-slate-900 dark:text-slate-100 min-h-[100px] placeholder-slate-500 dark:placeholder-slate-500 font-medium"
                   placeholder="เช่น เปลี่ยนพื้นหลังเป็นห้องเรียน, ทำให้ภาพดูเก่าแบบ retro, ลบวัตถุสีแดงออก..."
                   value={prompt}
                   onChange={(e) => setPrompt(e.target.value)}
                 />
               </div>

               <Button 
                 className="w-full font-bold" 
                 onClick={handleEdit} 
                 disabled={!image || !prompt || isProcessing}
                 isLoading={isProcessing}
               >
                 <Wand2 size={18} className="mr-2" /> สร้างสรรค์ภาพใหม่
               </Button>
            </div>
         </Card>

         {/* Result Section */}
         <Card title="ผลลัพธ์" icon={<Wand2 />}>
            <div className="h-full min-h-[400px] flex flex-col">
               <div className="flex-1 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center overflow-hidden p-4">
                  {isProcessing ? (
                    <div className="text-center">
                       <div className="animate-spin w-12 h-12 border-4 border-indigo-500 dark:border-indigo-500 border-t-transparent rounded-full mx-auto mb-4"></div>
                       <p className="text-slate-500 dark:text-slate-400 font-medium">กำลังประมวลผลด้วย Gemini 2.5...</p>
                    </div>
                  ) : resultImage ? (
                    <img src={resultImage} alt="Result" className="max-h-full max-w-full object-contain rounded-lg shadow-lg" />
                  ) : (
                    <p className="text-slate-400 dark:text-slate-600 text-sm font-medium">ภาพผลลัพธ์จะแสดงที่นี่</p>
                  )}
               </div>

               {resultImage && (
                 <div className="mt-4 flex justify-end">
                    <a href={resultImage} download="edited-image.png" className="w-full">
                       <Button variant="success" className="w-full font-bold">
                          <Download size={18} className="mr-2" /> ดาวน์โหลดรูปภาพ
                       </Button>
                    </a>
