export const Workload: React.FC = () => {
  const [sortBy, setSortBy] = useState<'workload_desc' | 'workload_asc' | 'name'>('workload_desc');
  const [filterSubject, setFilterSubject] = useState<string>('All');

  // Calculate workload dynamically including substitute history
  const data = TEACHERS.map(t => {
    // Count substituted classes from history where status is completed
    const subCount = MOCK_SUBSTITUTE_HISTORY.filter(
        h => h.substitute_id === t.id && h.status === 'completed'
    ).length;

    // Assume each substitution adds ~5% (mock logic) or use real calculation
    const subLoad = subCount * 5; 

    return {
      name: t.name,
      shortName: t.name.split(' ')[0],
      regularLoad: t.workload,
      subLoad: subLoad,
      totalLoad: t.workload + subLoad,
      subject: t.subject,
      grade: t.grade_level,
      full: t
    };
  });

  // Filter & Sort
  const filteredData = data.filter(d => 
      filterSubject === 'All' || d.subject === filterSubject
  ).sort((a, b) => {
      if (sortBy === 'workload_desc') return b.totalLoad - a.totalLoad;
      if (sortBy === 'workload_asc') return a.totalLoad - b.totalLoad;
      return a.name.localeCompare(b.name);
  });

  // Dynamic Height calculation: 60px per bar + header buffer
  const chartHeight = Math.max(500, filteredData.length * 60);

  // Get active workload limit rule
  const workloadRule = INITIAL_RULES.find(r => r.type === 'workload_balance' && r.active);
  const limitLine = workloadRule?.maxWorkload || 80;

  // Stats for sidebar
  const avgLoad = Math.round(filteredData.reduce((acc, curr) => acc + curr.totalLoad, 0) / (filteredData.length || 1));
  const overLoadCount = filteredData.filter(d => d.totalLoad > limitLine).length;
  const topContributor = filteredData.sort((a,b) => b.subLoad - a.subLoad)[0];

  const uniqueSubjects = Array.from(new Set(TEACHERS.map(t => t.subject)));

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
         <h2 className="text-2xl font-bold text-slate-900 dark:text-white">ภาระงานและสถิติ (Workload Analytics)</h2>
         <div className="flex flex-wrap gap-2 font-bold">
             <select 
                value={filterSubject}
                onChange={(e) => setFilterSubject(e.target.value)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-900 dark:text-slate-100 focus:border-indigo-500 dark:focus:border-indigo-500 outline-none"
             >
                <option value="All">ทุกวิชา (All Subjects)</option>
                {uniqueSubjects.map(s => <option key={s} value={s}>{s}</option>)}
             </select>
             <select 
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-900 dark:text-slate-100 focus:border-indigo-500 dark:focus:border-indigo-500 outline-none"
             >
                <option value="workload_desc">ภาระงานมาก-น้อย</option>
                <option value="workload_asc">ภาระงานน้อย-มาก</option>
                <option value="name">ชื่อ ก-ฮ</option>
             </select>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 font-bold">
         <div className="lg:col-span-2">
            <Card title={`กราฟเปรียบเทียบเชิงลึก (${filteredData.length} ท่าน)`} className="h-full min-h-[600px] flex flex-col">
               <div className="flex-1 w-full overflow-y-auto pr-2 custom-scrollbar" style={{ maxHeight: '600px' }}>
                 <div style={{ height: `${chartHeight}px`, width: '100%' }}>
                   <ResponsiveContainer width="100%" height="100%">
                     <BarChart 
                        data={filteredData} 
                        layout="vertical" 
                        margin={{ top: 20, right: 30, left: 40, bottom: 5 }}
                        barSize={20}
                        stackOffset="sign"
                     >
                       <CartesianGrid strokeDasharray="3 3" stroke="#cbd5e1" horizontal={false} className="dark:stroke-slate-800" />
                       <XAxis type="number" stroke="#94a3b8" domain={[0, 100]} />
                       <YAxis dataKey="shortName" type="category" stroke="#94a3b8" width={100} tick={{fontSize: 12, fontWeight: 'bold'}} />
                       <Tooltip 
                          cursor={{fill: '#94a3b8', opacity: 0.1}}
                          contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#f8fafc', borderRadius: '8px' }}
                          itemStyle={{ color: '#f8fafc', fontSize: '12px' }}
