                      <ImageIcon size={48} className="text-slate-400 dark:text-[#9CA3AF] mb-4" />
                      <p className="text-slate-600 dark:text-[#9CA3AF] font-extrabold">คลิกเพื่ออัพโหลดรูปภาพ</p>
                      <p className="text-xs text-slate-500 dark:text-[#9CA3AF] mt-2 font-bold italic">รองรับ PNG, JPG</p>
