                   />
                </div>
                <button onClick={() => toggleRule(rule.id)} className={`transition-colors ${rule.active ? 'text-emerald-500 dark:text-emerald-400' : 'text-[#9CA3AF]'}`} title={rule.active ? "ปิดใช้งาน" : "เปิดใช้งาน"}>
