                     <Bar dataKey="workload" radius={[0, 4, 4, 0]} barSize={20}>
                        {data.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.workload > 70 ? '#f87171' : entry.workload > 50 ? '#fbbf24' : '#4ade80'} />
                        ))}
                     </Bar>
                   </BarChart>
                 </ResponsiveContainer>
               </div>
            </Card>
         </div>

         <div>
            <Card title="สรุปสถานะ" className="h-full">
               <div className="space-y-4">
                  <div className="p-4 rounded-lg bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 shadow-sm">
                     <div className="text-xs font-extrabold text-[#9CA3AF] uppercase mb-1">ภาระงานเฉลี่ย</div>
                     <div className="text-3xl font-extrabold text-indigo-600 dark:text-indigo-400">
                        {Math.round(data.reduce((acc, curr) => acc + curr.workload, 0) / data.length)}%
                     </div>
                  </div>

                  <h4 className="text-sm font-extrabold text-slate-700 dark:text-slate-300 mt-4 mb-2">ครูที่มีภาระงานสูง (Overload)</h4>
                  <div className="space-y-2">
                     {data.filter(d => d.workload > 70).map(d => (
                        <div key={d.name} className="flex items-center justify-between p-3 rounded-lg bg-red-50 dark:bg-red-500/10 border border-red-100 dark:border-red-500/20 shadow-sm">
                           <span className="text-sm font-bold text-red-700 dark:text-red-300">{d.name}</span>
                           <span className="text-sm font-extrabold text-red-600 dark:text-red-400">{d.workload}%</span>
                        </div>
                     ))}
                     {data.filter(d => d.workload > 70).length === 0 && (
                        <div className="text-sm font-bold text-emerald-600 dark:text-emerald-400 italic">ไม่มีครูภาระงานเกินเกณฑ์</div>
                     )}
                  </div>

                  <h4 className="text-sm font-extrabold text-slate-700 dark:text-slate-300 mt-4 mb-2">ครูที่ภาระงานน้อย (Available)</h4>
                  <div className="space-y-2">
                     {data.filter(d => d.workload < 50).map(d => (
                        <div key={d.name} className="flex items-center justify-between p-3 rounded-lg bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-100 dark:border-emerald-500/20 shadow-sm">
                           <span className="text-sm font-bold text-emerald-700 dark:text-emerald-300">{d.name}</span>
                           <span className="text-sm font-extrabold text-emerald-600 dark:text-emerald-400">{d.workload}%</span>
                        </div>
                     ))}
                  </div>
               </div>
            </Card>
         </div>
      </div>
    </div>
  );
};

