export type View = 'dashboard' | 'schedule' | 'substitute' | 'rules' | 'approvals' | 'workload' | 'image-editor' | 'settings';

export interface Teacher {
  id: string;
  name: string;
  subject: string;
  grade_level: 'kindergarten' | 'primary_low' | 'primary_high' | 'secondary_low';
  workload: number; // calculated %
  teaching_hours: number;
  substitute_hours: number;
  other_hours: number;
  email: string;
  phone: string;
  status: 'active' | 'inactive';
  specialty: string;
  notes: string;
  avatar: string;
}

export interface WorkloadSettings {
  baseHours: number; // Standard hours per week (e.g., 20 or 40)
}

export interface TimeSlot {
  id: string;
  period_no: string;
  time_label: string;
}

export interface ScheduleItem {
  id: string;
  day_of_week: string;
  timeslot_id: string;
  period_no: string;
  class_name: string;
  grade_level: string;
  subject: string;
  teacher_id: string;
}

export interface Rule {
  id: string;
  name: string;
  type: 'grade_level' | 'workload_balance' | 'period_swap' | 'subject_match' | 'custom';
  value: string;
  priority: string;
  weight: number;
  active: boolean;
  targetGrade?: string;
  fallbackGrade?: string;
  maxWorkload?: number;
  tolerance?: number;
  maxSwapsPerWeek?: number;
  allowCrossDay?: boolean;
  noticePeriodDays?: number;
  maxSwapWindowDays?: number;
  allowedReasons?: string[];
}

export interface Approval {
  id: string;
  date: string;
  teacher_id: string;
  substitute_id: string;
  period: string;
  subject: string;
  status: 'pending' | 'approved' | 'rejected';
  requestedBy: string;
  requestedAt: string;
  reason?: string;
}

export interface Notification {
  id: string;
  type: 'info' | 'warning' | 'alert' | 'success';
  title: string;
  message: string;
  time: string;
}

export interface SubstituteHistoryItem {
  id: string;
  date: string;
  period: string;
  subject: string;
  teacher_id: string;
  substitute_id: string;
  status: 'completed' | 'cancelled';
}

export interface PeriodSwapItem {
  id: string;
  date: string;
  requester_id: string;
  responder_id: string;
  req_period: string;
  res_period: string;
  req_subject: string;
  res_subject: string;
  status: 'approved' | 'pending' | 'rejected' | 'completed';
  reason: string;
}

export interface RuleSuggestion {
  ruleId: string;
  title: string;
  description: string;
  action: 'modify' | 'create' | 'remove';
  suggestedChanges?: Partial<Rule>;
}

export interface RuleAnalysisResult {
  analysis: string;
  overallScore: number;
  suggestions: RuleSuggestion[];
}

export interface WorkloadInsight {
  summary: string;
  recommendations: string[];
  riskTeachers: string[];
}

export interface SheetConfig {
  spreadsheetId: string;
  apiKey: string;
  accessToken?: string;
}

export interface ChatHistoryItem {
  role: 'user' | 'model';
  text: string;
}

